import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused kernel for scaling, Hardtanh, and GELU
fused_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_op_kernel(const float* input, float* output, float scale, float min_val, float max_val, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        // Scale input
        float val = input[idx] * scale;

        // Apply Hardtanh
        val = fmaxf(fminf(val, max_val), min_val);

        // Approximate GELU
        const float sqrt_2_over_pi = 0.7978845608028654f;
        const float gelu_coeff = 0.044715f;
        float cube = val * val * val;
        float inner = sqrt_2_over_pi * (val + gelu_coeff * cube);
        output[idx] = 0.5f * val * (1.0f + tanhf(inner));
    }
}

torch::Tensor fused_op_cuda(torch::Tensor input, float scale, float min_val, float max_val) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    fused_op_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        scale,
        min_val,
        max_val,
        num_elements
    );

    return output;
}
"""

fused_kernel_cpp = "torch::Tensor fused_op_cuda(torch::Tensor input, float scale, float min_val, float max_val);"

fused_op = load_inline(
    name="fused_op",
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_source,
    functions=["fused_op_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, scaling_factor, hardtanh_min, hardtanh_max):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.scaling_factor = scaling_factor
        self.hardtanh_min = hardtanh_min
        self.hardtanh_max = hardtanh_max

    def forward(self, x):
        x = self.gemm(x)
        x = fused_op.fused_op_cuda(x, self.scaling_factor, self.hardtanh_min, self.hardtanh_max)
        return x
